-- TEST-ONLY COMPATIBILITY OVERRIDE: pg_cron extension unavailable in native local PostgreSQL; migration has no cron.* references. Original migration remains unchanged.

create table if not exists supplier_ingredient_terms (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,supplier_id uuid not null references suppliers(id) on delete cascade,lead_time_days numeric(12,4) not null check (lead_time_days >= 0),minimum_order_quantity numeric(18,6) check (minimum_order_quantity is null or minimum_order_quantity > 0),order_multiple numeric(18,6) check (order_multiple is null or order_multiple > 0),active boolean not null default true,effective_from timestamptz not null default now(),created_at timestamptz not null default now(),unique(business_id, ingredient_id, supplier_id));
create table if not exists supplier_recommendations (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,supplier_id uuid not null references suppliers(id) on delete cascade,score numeric(8,4) not null check (score >= 0 and score <= 100),rank integer not null check (rank > 0),price_score numeric(8,4) not null default 0,lead_time_reliability_score numeric(8,4) not null default 0,delivery_completion_score numeric(8,4) not null default 0,recommended boolean not null default false,calculated_at timestamptz not null default now(),unique(business_id, ingredient_id, supplier_id));
create index if not exists idx_v17_terms_lookup on supplier_ingredient_terms(business_id,ingredient_id,active,effective_from desc); create index if not exists idx_v17_recommendations on supplier_recommendations(business_id,ingredient_id,recommended,rank);
create table if not exists ingredient_daily_consumption (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,demand_date date not null,unit text not null,consumed_quantity numeric(24,8) not null default 0 check(consumed_quantity>=0),source_movement_count integer not null default 0,source_max_created_at timestamptz,refreshed_at timestamptz not null default now(),unique(business_id,ingredient_id,demand_date,unit));
create index if not exists idx_v17_daily_demand_window on ingredient_daily_consumption(business_id,ingredient_id,demand_date desc);
create table if not exists demand_forecasts (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,ingredient_id uuid not null references ingredients(id) on delete cascade,unit text not null,window_days integer not null check(window_days between 1 and 3650),history_days integer not null default 0,average_daily_demand numeric(24,8) not null default 0,maximum_daily_demand numeric(24,8) not null default 0,lead_time_days numeric(12,4) not null default 0,safety_stock numeric(24,8) not null default 0,reorder_point numeric(24,8) not null default 0,current_stock numeric(24,8) not null default 0,stock_below_rop boolean not null default false,cold_start boolean not null default true,unit_mismatch_count integer not null default 0,supplier_id uuid references suppliers(id),supplier_score numeric(8,4),calculation_version text not null default 'v1.7.0',calculated_at timestamptz not null default now(),unique(business_id,ingredient_id));
create index if not exists idx_v17_forecasts_action on demand_forecasts(business_id,stock_below_rop,calculated_at desc);
create table if not exists purchase_plans (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,supplier_id uuid references suppliers(id),status text not null default 'draft' check(status in ('draft','approved','ordered','received','cancelled')),source text not null default 'demand_forecast',forecast_calculated_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(business_id,supplier_id,status,source));
create table if not exists purchase_plan_lines (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,purchase_plan_id uuid not null references purchase_plans(id) on delete cascade,ingredient_id uuid not null references ingredients(id),unit text not null,current_stock numeric(24,8) not null,reorder_point numeric(24,8) not null,suggested_quantity numeric(24,8) not null check(suggested_quantity>0),supplier_id uuid references suppliers(id),created_at timestamptz not null default now(),unique(purchase_plan_id,ingredient_id));
create index if not exists idx_v17_plan_lines on purchase_plan_lines(business_id,purchase_plan_id,ingredient_id);
create or replace view public.v17_current_stock with (security_invoker=true) as select im.business_id,im.ingredient_id,i.base_unit as unit,coalesce(sum(im.quantity) filter(where im.unit=i.base_unit),0)::numeric(24,8) as current_stock,count(*) filter(where im.unit<>i.base_unit)::integer as unit_mismatch_count from inventory_movements im join ingredients i on i.id=im.ingredient_id and i.business_id=im.business_id group by im.business_id,im.ingredient_id,i.base_unit;
create or replace function public.refresh_v17_daily_consumption(p_business_id uuid,p_window_days integer default 90) returns integer language plpgsql security definer set search_path=public as $$ declare affected integer; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if p_window_days<1 or p_window_days>3650 then raise exception 'window_days must be between 1 and 3650'; end if; insert into ingredient_daily_consumption(business_id,ingredient_id,demand_date,unit,consumed_quantity,source_movement_count,source_max_created_at,refreshed_at) select im.business_id,im.ingredient_id,(im.created_at at time zone b.timezone)::date,i.base_unit,sum(abs(im.quantity))::numeric(24,8),count(*)::integer,max(im.created_at),now() from inventory_movements im join ingredients i on i.id=im.ingredient_id and i.business_id=im.business_id join businesses b on b.id=im.business_id where im.business_id=p_business_id and im.movement_type='consumption' and im.created_at>=now()-make_interval(days=>p_window_days) and im.unit=i.base_unit group by im.business_id,im.ingredient_id,demand_date,i.base_unit on conflict(business_id,ingredient_id,demand_date,unit) do update set consumed_quantity=excluded.consumed_quantity,source_movement_count=excluded.source_movement_count,source_max_created_at=excluded.source_max_created_at,refreshed_at=now(); delete from ingredient_daily_consumption d where d.business_id=p_business_id and d.demand_date<current_date-p_window_days; get diagnostics affected=row_count; return affected; end; $$;
create or replace function public.refresh_v17_forecasts(p_business_id uuid,p_window_days integer default 90) returns integer language plpgsql security definer set search_path=public as $$ declare forecast_count integer; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; perform public.refresh_v17_daily_consumption(p_business_id,p_window_days); with bounds as(select i.id ingredient_id,i.base_unit unit,greatest(1,p_window_days) window_days from ingredients i where i.business_id=p_business_id),days as(select b.ingredient_id,b.unit,gs::date demand_date from bounds b cross join lateral generate_series(current_date-(b.window_days-1),current_date,interval '1 day') gs),daily as(select d.ingredient_id,d.unit,d.demand_date,coalesce(x.consumed_quantity,0)::numeric(24,8) demand from days d left join ingredient_daily_consumption x on x.business_id=p_business_id and x.ingredient_id=d.ingredient_id and x.demand_date=d.demand_date and x.unit=d.unit),stats as(select ingredient_id,unit,avg(demand)::numeric(24,8) avg_demand,max(demand)::numeric(24,8) max_demand,count(*) filter(where demand>0)::integer history_days from daily group by ingredient_id,unit),terms as(select distinct on(t.business_id,t.ingredient_id)t.ingredient_id,t.supplier_id,t.lead_time_days from supplier_ingredient_terms t where t.business_id=p_business_id and t.active order by t.business_id,t.ingredient_id,t.effective_from desc),recs as(select distinct on(r.business_id,r.ingredient_id)r.ingredient_id,r.supplier_id,r.score from supplier_recommendations r where r.business_id=p_business_id and r.recommended order by r.business_id,r.ingredient_id,r.rank,r.score desc),selected_supplier as(select s.ingredient_id,coalesce(r.supplier_id,t.supplier_id) supplier_id,coalesce(t.lead_time_days,0)::numeric(12,4) lead_time_days,r.score from stats s left join recs r on r.ingredient_id=s.ingredient_id left join terms t on t.ingredient_id=s.ingredient_id and t.supplier_id=r.supplier_id),stock as(select business_id,ingredient_id,unit,current_stock,unit_mismatch_count from v17_current_stock where business_id=p_business_id),calc as(select p_business_id business_id,s.ingredient_id,s.unit,p_window_days window_days,s.history_days,s.avg_demand average_daily_demand,s.max_demand maximum_daily_demand,coalesce(ss.lead_time_days,0)::numeric(12,4) lead_time_days,greatest(0,(s.max_demand-s.avg_demand)*coalesce(ss.lead_time_days,0))::numeric(24,8) safety_stock,greatest(0,(s.avg_demand*coalesce(ss.lead_time_days,0))+greatest(0,(s.max_demand-s.avg_demand)*coalesce(ss.lead_time_days,0)))::numeric(24,8) reorder_point,coalesce(st.current_stock,0)::numeric(24,8) current_stock,coalesce(st.unit_mismatch_count,0)::integer unit_mismatch_count,ss.supplier_id,ss.score,(s.history_days=0) cold_start from stats s left join selected_supplier ss on ss.ingredient_id=s.ingredient_id left join stock st on st.ingredient_id=s.ingredient_id and st.unit=s.unit) insert into demand_forecasts(business_id,ingredient_id,unit,window_days,history_days,average_daily_demand,maximum_daily_demand,lead_time_days,safety_stock,reorder_point,current_stock,stock_below_rop,cold_start,unit_mismatch_count,supplier_id,supplier_score,calculation_version,calculated_at) select business_id,ingredient_id,unit,window_days,history_days,average_daily_demand,maximum_daily_demand,lead_time_days,safety_stock,reorder_point,current_stock,current_stock<reorder_point,cold_start,unit_mismatch_count,supplier_id,score,'v1.7.0',now() from calc on conflict(business_id,ingredient_id) do update set unit=excluded.unit,window_days=excluded.window_days,history_days=excluded.history_days,average_daily_demand=excluded.average_daily_demand,maximum_daily_demand=excluded.maximum_daily_demand,lead_time_days=excluded.lead_time_days,safety_stock=excluded.safety_stock,reorder_point=excluded.reorder_point,current_stock=excluded.current_stock,stock_below_rop=excluded.stock_below_rop,cold_start=excluded.cold_start,unit_mismatch_count=excluded.unit_mismatch_count,supplier_id=excluded.supplier_id,supplier_score=excluded.supplier_score,calculation_version=excluded.calculation_version,calculated_at=now(); select count(*) into forecast_count from demand_forecasts where business_id=p_business_id; insert into audit_logs(business_id,user_id,action,entity_type,metadata) values(p_business_id,auth.uid(),'DemandForecastSnapshot','demand_forecast',jsonb_build_object('calculation_version','v1.7.0','window_days',p_window_days,'snapshot_at',now(),'forecast_count',forecast_count,'formula',jsonb_build_object('ADD','sum(daily exact-unit consumption) / window_days','SS','max(0, (maximum_daily_demand - average_daily_demand) * lead_time_days)','ROP','(average_daily_demand * lead_time_days) + safety_stock'),'unit_policy','ingredient.base_unit must equal ledger movement unit; mismatches are excluded and flagged','cold_start_policy','zero-history ingredients use ADD=0, maximum_daily_demand=0, SS=0 and ROP=0 until consumption exists')); return forecast_count; end; $$;
create or replace function public.create_v17_purchase_drafts(p_business_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare created_lines integer; plan_id uuid; rec record; qty numeric(24,8); minimum_qty numeric(18,6); multiple_qty numeric(18,6); begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; for rec in select f.*,t.minimum_order_quantity,t.order_multiple from demand_forecasts f left join supplier_ingredient_terms t on t.business_id=f.business_id and t.ingredient_id=f.ingredient_id and t.supplier_id=f.supplier_id and t.active where f.business_id=p_business_id and f.stock_below_rop and f.supplier_id is not null and f.unit_mismatch_count=0 and not f.cold_start loop qty:=greatest(rec.reorder_point-rec.current_stock,0); minimum_qty:=coalesce(rec.minimum_order_quantity,0); multiple_qty:=coalesce(rec.order_multiple,0); qty:=greatest(qty,minimum_qty); if multiple_qty>0 then qty:=ceil(qty/multiple_qty)*multiple_qty; end if; if qty<=0 then continue; end if; insert into purchase_plans(business_id,supplier_id,status,source,forecast_calculated_at,created_by) values(p_business_id,rec.supplier_id,'draft','demand_forecast',rec.calculated_at,auth.uid()) on conflict(business_id,supplier_id,status,source) do update set forecast_calculated_at=excluded.forecast_calculated_at returning id into plan_id; if plan_id is null then select id into plan_id from purchase_plans where business_id=p_business_id and supplier_id=rec.supplier_id and status='draft' and source='demand_forecast'; end if; insert into purchase_plan_lines(business_id,purchase_plan_id,ingredient_id,unit,current_stock,reorder_point,suggested_quantity,supplier_id) values(p_business_id,plan_id,rec.ingredient_id,rec.unit,rec.current_stock,rec.reorder_point,qty,rec.supplier_id) on conflict(purchase_plan_id,ingredient_id) do update set current_stock=excluded.current_stock,reorder_point=excluded.reorder_point,suggested_quantity=excluded.suggested_quantity,supplier_id=excluded.supplier_id; end loop; select count(*) into created_lines from purchase_plan_lines l join purchase_plans p on p.id=l.purchase_plan_id where p.business_id=p_business_id and p.status='draft' and p.source='demand_forecast'; insert into audit_logs(business_id,user_id,action,entity_type,metadata) values(p_business_id,auth.uid(),'DemandForecastAutoDraft','purchase_plan',jsonb_build_object('line_count',created_lines,'created_at',now())); return created_lines; end; $$;
alter table supplier_ingredient_terms enable row level security; alter table supplier_recommendations enable row level security; alter table ingredient_daily_consumption enable row level security; alter table demand_forecasts enable row level security; alter table purchase_plans enable row level security; alter table purchase_plan_lines enable row level security;
create policy v17_terms_select on supplier_ingredient_terms for select using(is_member(business_id)); create policy v17_terms_manage on supplier_ingredient_terms for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy v17_recommendations_select on supplier_recommendations for select using(is_member(business_id)); create policy v17_recommendations_manage on supplier_recommendations for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy v17_daily_select on ingredient_daily_consumption for select using(is_member(business_id)); create policy v17_forecasts_select on demand_forecasts for select using(is_member(business_id)); create policy v17_plans_select on purchase_plans for select using(is_member(business_id)); create policy v17_plans_manage on purchase_plans for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[])); create policy v17_lines_select on purchase_plan_lines for select using(is_member(business_id)); create policy v17_lines_manage on purchase_plan_lines for all using(has_role(business_id,ARRAY['owner','manager']::member_role[])) with check(has_role(business_id,ARRAY['owner','manager']::member_role[]));
revoke all on function public.refresh_v17_daily_consumption(uuid,integer) from anon; revoke all on function public.refresh_v17_forecasts(uuid,integer) from anon; revoke all on function public.create_v17_purchase_drafts(uuid) from anon; grant execute on function public.refresh_v17_daily_consumption(uuid,integer) to authenticated; grant execute on function public.refresh_v17_forecasts(uuid,integer) to authenticated; grant execute on function public.create_v17_purchase_drafts(uuid) to authenticated;